<?php declare(strict_types=1);require_once __DIR__.'/../includes/customer-auth.php';require_once __DIR__.'/../classes/Product.php';require_once __DIR__.'/../classes/Order.php';requireCustomerLogin();$c=(int)$_SESSION['customer_id'];$error=null;if($_SERVER['REQUEST_METHOD']==='POST'){if(!verifyCsrfToken($_POST['csrf_token']??null))$error='نشست منقضی شده است.';else try{if(($_POST['action']??'')==='add')Order::add($c,(int)$_POST['product_id']);else Order::updateCart($c,(int)$_POST['product_id'],(int)$_POST['quantity']);header('Location: cart');exit;}catch(Throwable $e){$error=$e->getMessage();}}$items=Order::cart($c);$total=array_sum(array_map(fn($i)=>(int)$i['price']*(int)$i['quantity'],$items));$csrf=htmlspecialchars(csrfToken(),ENT_QUOTES,'UTF-8');?>
<!doctype html><html lang="fa" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>سبد خرید</title><link rel="stylesheet" href="assets/css/customer-auth.css"></head><body class="customer-auth cart-page"><main class="cart-layout"><header class="cart-header"><a href="index">← بازگشت به منو</a><h1>سبد خرید</h1><span><?=count($items)?> محصول</span></header><?php if($error):?><div class="auth-alert"><?=htmlspecialchars($error)?></div><?php endif;?><?php if(!$items):?><section class="cart-empty"><h2>سبد خرید شما خالی است</h2><p>محصولات مورد علاقه‌تان را انتخاب کنید.</p><a class="auth-submit" href="index">مشاهده منو</a></section><?php else:?><div class="cart-grid"><section class="cart-items"><?php foreach($items as $i):$q=(int)$i['quantity'];?><article class="cart-item"><div class="cart-product-image"><?= $i['image']?'<img src="uploads/'.htmlspecialchars($i['image'],ENT_QUOTES,'UTF-8').'" alt="">':'☕'?></div><div class="cart-product-info"><h2><?=htmlspecialchars($i['name'])?></h2><p><?=number_format((float)$i['price'])?> تومان برای هر عدد</p><strong><?=number_format((float)$i['price']*$q)?> تومان</strong></div><div class="cart-item-actions"><form method="post" class="quantity-control"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?=$i['product_id']?>"><button name="quantity" value="<?=$q-1?>" aria-label="کاهش تعداد">−</button><output><?=$q?></output><button name="quantity" value="<?=$q+1?>" aria-label="افزایش تعداد">+</button></form><form method="post"><input type="hidden" name="csrf_token" value="<?=$csrf?>"><input type="hidden" name="action" value="update"><input type="hidden" name="product_id" value="<?=$i['product_id']?>"><button class="remove-item" name="quantity" value="0">حذف</button></form></div></article><?php endforeach;?></section><aside class="cart-summary"><h2>خلاصه سفارش</h2><p>تعداد اقلام <b><?=array_sum(array_column($items,'quantity'))?> عدد</b></p><div class="total">مبلغ کل <b><?=number_format((float)$total)?> تومان</b></div><a class="auth-submit" href="checkout">ادامه و ثبت سفارش ←</a><small>پرداخت آنلاین ندارد؛ سفارش ابتدا بررسی می‌شود.</small></aside></div><?php endif;?></main></body></html>
